-- Gerado por render_sql.py. Proposta sentinela-classificacao-v2: nenhuma regra homologada.
\set ON_ERROR_STOP on
BEGIN;
DO $guard$ BEGIN
  IF inet_server_port() <> 55487 OR inet_server_addr() <> inet '127.0.0.1'
     OR current_setting('sentinela.sandbox_uuid', true) IS NULL OR current_database() <> 'sentinela_pcdf_local' THEN
    RAISE EXCEPTION 'Script restrito ao clone descartavel 127.0.0.1:55487.';
  END IF;
END $guard$;

CREATE TEMP TABLE catalogo_antes ON COMMIT DROP AS SELECT (SELECT count(*) FROM sentinela.categorias_criminais WHERE versao_catalogo='sentinela-categorias-v2') AS categorias;
DO $post$ DECLARE antes record; BEGIN
  SELECT * INTO antes FROM catalogo_antes;
  IF (SELECT count(*) FROM sentinela.categorias_criminais WHERE versao_catalogo='sentinela-categorias-v2' AND status='pendente') <> 23
     OR (SELECT count(*) FROM sentinela.mapeamentos_natureza WHERE versao='pcdf-classificacao-v2' AND status='pendente' AND categoria_id IS NULL) <> 43
     OR (SELECT count(DISTINCT natureza_id) FROM sentinela.mapeamentos_natureza WHERE versao='pcdf-classificacao-v2') <> 41 THEN
    RAISE EXCEPTION 'Catalogo proposto divergente.';
  END IF;
  IF antes.categorias = 0 THEN
      'catalogo.classificacao.proposta_registrada', jsonb_build_object('catalogo','sentinela-categorias-v2','mapeamento','pcdf-classificacao-v2',
      'categorias',23,'mapeamentosPendentes',43,'homologadas',0), 'Proposta de classificacao v2 sem homologacao (ensaio em clone).');
  END IF;
END $post$;
COMMIT;
